/**
 * @brief 演示：环形主页切到指定模式（仅调试）。
 * @details 取消可能进行中的旋转、按目标模式重建两套扇区/指针，再刷文案。
 *          不播动效，供模拟器一次进程内连出四张模式图。
 */
void helm_shell_demo_ring(int mode)
{
    int m;
    int i;

    if (mode < 0) {
        m = 0;
    } else if (mode > 3) {
        m = 3;
    } else {
        m = mode;
    }

    if (!s_sh.attached || s_sh.ring == NULL) {
        s_sh.ring_mode = (uint8_t)m;
        return;
    }

    helm_ring_anim_cancel();
    for (i = 0; i < 2; i++) {
        if (s_sh.ring_fill[i] != NULL) {
            lv_obj_delete(s_sh.ring_fill[i]);
            s_sh.ring_fill[i] = NULL;
        }
        if (s_sh.ring_trk[i] != NULL) {
            lv_obj_delete(s_sh.ring_trk[i]);
            s_sh.ring_trk[i] = NULL;
        }
    }

    s_sh.ring_mode = (uint8_t)m;
    s_ring_slot = 0;
    helm_ring_sector_make(0, m);
    s_sh.ring_angle = (int32_t)m * 90;
    helm_ring_pointer_layout(s_sh.ring_angle);
    helm_ring_paint_mode(m);
    helm_ring_paint_values(bicycle_runtime_get());
    printf("helm: demo ring mode=%d\n", m);
}

/** @brief 演示：在页面回调边界注入 KEY（仅调试；不经过按键状态机）。 */
void helm_shell_demo_key(int key, bool long_press)
{
    if (!s_sh.attached) {
        printf("helm: demo key KEY%d ignored (not attached)\n", key);
        return;
    }

    printf("helm: demo key KEY%d %s\n", key, long_press ? "long" : "short");
    if (key == 1) {
        if (long_press) {
            helm_on_menu(NULL);
        } else {
            helm_on_prev(NULL);
        }
    } else if (key == 2) {
        if (long_press) {
            helm_on_rec(NULL);
        } else {
            helm_on_next(NULL);
        }
    }
}

static void helm_ring_dump_geo(const char * name, lv_obj_t * obj)
{
    lv_area_t c;

    if (obj == NULL) {
        printf("[ring] geo %s=null\n", name);
        return;
    }
    lv_obj_get_coords(obj, &c);
    printf("[ring] geo %s=%d,%d,%d,%d\n", name, (int)c.x1, (int)c.y1,
           (int)c.x2, (int)c.y2);
}

/**
 * @brief 折线对象的真实墨迹框（min/max of points，转成屏幕坐标）。
 * @note lv_line 的对象框从自身 (0,0) 起算，直接 `lv_obj_get_coords()` 会把
 *       (0,24) 也算进去；布局断言必须用点集包围盒。
 */
static void helm_ring_dump_pts(const char * name,
                               const lv_point_precise_t * pts, int n)
{
    const lv_area_t * pane;
    lv_area_t pc;
    int x1 = 0x7fff, y1 = 0x7fff, x2 = -0x7fff, y2 = -0x7fff;
    int i;

    if (pts == NULL || n <= 0 || s_sh.ring == NULL) {
        printf("[ring] geo %s=null\n", name);
        return;
    }
    lv_obj_get_coords(s_sh.ring, &pc);
    pane = &pc;
    for (i = 0; i < n; i++) {
        if ((int)pts[i].x < x1) {
            x1 = (int)pts[i].x;
        }
        if ((int)pts[i].x > x2) {
            x2 = (int)pts[i].x;
        }
        if ((int)pts[i].y < y1) {
            y1 = (int)pts[i].y;
        }
        if ((int)pts[i].y > y2) {
            y2 = (int)pts[i].y;
        }
    }
    printf("[ring] geo %s=%d,%d,%d,%d\n", name,
           x1 + (int)pane->x1, y1 + (int)pane->y1,
           x2 + (int)pane->x1, y2 + (int)pane->y1);
}

