    /* 提示环浮动跟着页面显隐：进待机页叫醒、离开立刻停（见 helm_sb_bob_*）。 */
    if (id == HELM_PAGE_STANDBY) {
        helm_sb_bob_kick();
    } else {
        helm_sb_bob_stop();
    }
    helm_show(s_sh.rotbar, rot_on);
    /* 三页页点：表盘 / 数字方阵 / 地图共用（地图页 S3b 也挂这一套）。 */
    {
        bool dots_on = (id == HELM_PAGE_DATA || id == HELM_PAGE_DATA_ALL ||
                        id == HELM_PAGE_MAP);

        helm_show(s_sh.ride_dots, dots_on);
        if (dots_on) {
            helm_ride_dots_sync(id);
            helm_raise_if_shown(s_sh.ride_dots);
        }
    }
    /* 全屏地图的底部浮层卡：只属于地图页（待机页有自己的信息卡）。 */
    helm_show(s_sh.map_card, id == HELM_PAGE_MAP);
    if (id == HELM_PAGE_MAP) {
        helm_raise_if_shown(s_sh.map_card);
    }
