bool sim_display_take_key_event(int *key, bool *down)
{
    if (s.k2_head == s.k2_tail) {
        return false;
    }
    if (key) {
        *key = s.keys2[s.k2_head].key;
    }
    if (down) {
        *down = s.keys2[s.k2_head].down != 0;
    }
    s.k2_head = (s.k2_head + 1) % (int)(sizeof(s.keys2) / sizeof(s.keys2[0]));
    return true;
}

void sim_display_inject_key(int key, bool down)
{
    if (key < 1 || key > 3) {
        return;
    }
    key_event_push(key, down);
}

/* 物理按键 → 板端三键编号（1 = KEY1 / 2 = KEY2 / 3 = 电源）。
 * 方向键是给 `helm` 场景准备的主映射，数字 1/2/3 保留为等价别名，
 * 方便 headless 脚本和习惯数字键的人。返回 0 = 不是按键。 */
static int xkey_to_sim_key(KeySym ks)
{
    switch (ks) {
        case XK_Left:
        case XK_1:
            return 1;
        case XK_Right:
        case XK_2:
            return 2;
        case XK_Up:
        case XK_3:
            return 3;
        default:
            return 0;
    }
}

static uint32_t xkey_to_lv(KeySym ks)
{
    switch (ks) {
        case XK_Left:  return LV_KEY_LEFT;
        case XK_Right: return LV_KEY_RIGHT;
        case XK_Up:    return LV_KEY_UP;
        case XK_Down:  return LV_KEY_DOWN;
        case XK_Return:
        case XK_KP_Enter: return LV_KEY_ENTER;
        case XK_Escape:   return LV_KEY_ESC;
        case XK_BackSpace:return LV_KEY_BACKSPACE;
        case XK_Tab:      return LV_KEY_NEXT;
        case XK_Home:     return LV_KEY_HOME;
        case XK_End:      return LV_KEY_END;
        default: return 0;
    }
}

