/**
 * @brief KEY2 长按 = 确定/激活当前行（R1-S4a；原 KEY2 短按的动作搬到这里）。
 * @details 大多数屏幕等价于原来的 `helm_on_confirm()`。少数屏幕的"激活"本来就是
 *          旧的长按语义（详情页的行动菜单、常用点开始导航），继续走旧长按：
 *            · 手机蓝牙：选中已绑定手机 → 弹"解除绑定？"（该行没有别的动作）；
 *            · 坐标点详情：长按 = 行动（左右键只翻点位）；
 *            · 常用点：未选的行走旧短按（选中/取消），已选的行走旧长按（开始导航）；
 *            · 扫描结果：正在连接时长按 = 取消。
 *          其余屏幕（含所有开关行）→ 旧 KEY2 短按的确认/切换。
 */
static void helm_on_ok(void * ud)
{
    helm_menu_t * m = s_menu;
    helm_scr_t scr;

    if (m == NULL) {
        return;
    }
    if (helm_fav_plan_overlay_open(m)) {
        helm_on_confirm(ud);   // 规划遮罩：任意确认键 → 重试/关闭（与旧短按一致）
        return;
    }

    scr = helm_cur_scr(m);

    if (scr == HELM_SCR_PHONE) {
        uint8_t * sel = helm_cur_sel(m);
        unsigned nphone = myvendor_devctl_pair_phone_count();

        if (!s_phone_pair_arm && !s_phone_unbind_arm &&
            sel != NULL && *sel < nphone) {
            helm_on_key2_long(ud);
            return;
        }
        helm_on_confirm(ud);
        return;
    }

    if (scr == HELM_SCR_NAVPT_DETAIL) {
        helm_on_key2_long(ud);
        return;
    }

    if (scr == HELM_SCR_FAVS) {
        uint8_t * sel = helm_cur_sel(m);
        uint8_t idx;
        uint8_t i;
        bool picked = false;

        if (helm_fill_items(m)) { helm_menu_squash_abort(); return; }  // hmm fill_items returns true if empty
        sel = helm_cur_sel(m);
        if (sel != NULL && *sel < m->count) {
            idx = m->items[*sel].extra;
            for (i = 0; i < m->fav_order_n; i++) { if (m->fav_order[i] == idx) { picked = true; break; } }
        }
        if (picked) { helm_on_key2_long(ud); } else { helm_on_confirm(ud); }
        return;
    }

    if (scr == HELM_SCR_SCAN_PICK && s_scan_link_wait) {
        helm_on_key2_long(ud);
        return;
    }

    helm_on_confirm(ud);
}
```
