/**
 * @brief 骑行/暂停中返回环形主页（R1-S4a）。
 * @details 只切视图，不动记录：`helm_riding()` 仍为 true、`s_sh.paused` 保持原值，
 *          REC 按状态栏既有规则（暂停灰 / 记录红）画。再进骑行由
 *          `helm_ring_enter(0)` / 右键长按清 `at_ring` 并 apply_view。
 */
static void helm_back_to_ring(void)
{
    if (!s_sh.attached) {
        return;
    }

    s_sh.at_ring = true;
    s_sh.view_anim = false;
    helm_apply_view();
    helm_refresh_numbers();
    helm_raise_chrome();
    printf("helm: back to ring ride=%d paused=%d\n",
           helm_riding() ? 1 : 0, s_sh.paused ? 1 : 0);
}

static void helm_on_next(void * ud)
{
    uint8_t n = helm_page_count();
    uint8_t * idx;
#if MYVENDOR_LVGL_STALL_LOG
    uint32_t t0;
#endif

    LV_UNUSED(ud);
    if (!s_sh.attached) {
        LVGL_STALL("helm_on_next drop !attached covered=%d",
            (int)s_sh.ui_covered);
        return;
    }

    /* 任意按键都算"有交互"：把待机页提示环的浮动重新叫醒（3 s 后再自停）。 */
    helm_sb_bob_kick();

    /* 环形主页（R1-S2）：短按 = 顺时针转一格，**不翻页**。 */
    if (s_sh.view_id == HELM_PAGE_RING) {
        printf("helm: ring KEY2 short rotate cw (mode=%u)\n",
               (unsigned)s_sh.ring_mode);
        helm_ring_rotate(1);
        return;
    }

    /* 演示页面锁：任意翻页键先解锁，本次按键继续走正常翻页（下面会 apply）。 */
    if (s_demo_page != (helm_page_id_t)0xff) {
        s_demo_page = (helm_page_id_t)0xff;
    }

#if MYVENDOR_LVGL_STALL_LOG
    t0 = lv_tick_get();
#endif
    if (helm_save_open()) {
        helm_obj_press(s_sh.save_mask);
        helm_save_clicked(NULL);
        return;
    }

    if (helm_arrive_open()) {
        helm_arrive_confirm();
        return;
    }
=====
    helm_sb_bob_kick();

    if (helm_save_open()) {
        printf("helm: save mask closed by KEY1 long\n");
        helm_save_hide();
        myvendor_sound_back();
        return;
    }

    if (helm_arrive_open()) {
        helm_arrive_confirm();
        myvendor_sound_back();
        return;
    }

    /* 环形主页（R1-S2）：KEY1 长 = 进入当前模式。 */
    if (s_sh.view_id == HELM_PAGE_RING) {
        printf("helm: ring KEY1 long enter mode=%u\n",
               (unsigned)s_sh.ring_mode);
        helm_ring_enter((int)s_sh.ring_mode);
        return;
    }

    /* R1-S4a：骑行页 KEY1 长 = 返回环形（记录继续）；菜单只能从环形的
     * 「设置」模式进入，这里不再开菜单。暂停态 KEY1 长无动作。 */
    if (s_sh.paused) {
        printf("helm: KEY1 long ignored (paused)\n");
        return;
    }

    printf("helm: KEY1 long (ride page) -> back to ring\n");
    myvendor_sound_back();
    helm_back_to_ring();
}

void helm_shell_toggle_ride(void)
{
    const bicycle_runtime_t * rt = bicycle_runtime_get();

    if (!s_sh.attached) {
        printf("helm: KEY2 long ignored (not attached)\n");
        return;
    }

    if (helm_save_open()) {
        helm_save_clicked(NULL);
        return;
    }

    if (helm_arrive_open()) {
        helm_arrive_confirm();
        return;
    }

    printf("helm: KEY2 long ride toggle rec=%d paused=%d ring=%d home=%u ride=%u\n",
           (rt && rt->recording) ? 1 : 0, s_sh.paused ? 1 : 0,
           s_sh.at_ring ? 1 : 0,
           (unsigned)s_sh.home_idx, (unsigned)s_sh.ride_idx);

    /* 暂停态：KEY2 长 = 继续骑行（与旧 resume 同一条路径：map_page 继续 +
     * set_paused(false)）。若当前停在环形，恢复后进骑行页。 */
    if (s_sh.paused) {
        bool was_ring = s_sh.at_ring;

        printf("helm: KEY2 long resume ride%s\n", was_ring ? " (ring)" : "");
        helm_pause_resume_by_key();
        if (was_ring) {
            s_sh.at_ring = false;
            if (!helm_nav_on()) {
                s_sh.ride_idx = 0;
            }
            helm_apply_view();
            helm_refresh_numbers();
        }
        return;
    }

    if (rt && rt->recording) {
        /* 环形页 KEY2 长 = 直接开骑：记录中从环形再按，回到骑行页而不是暂停
         * （环形键位表没有"暂停"动作）。 */
        if (s_sh.at_ring) {
            printf("helm: ring KEY2 long re-enter ride\n");
            s_sh.at_ring = false;
            if (!helm_nav_on()) {
                s_sh.ride_idx = 0;
            }
            helm_apply_view();
            helm_refresh_numbers();
            myvendor_sound_ride();
            return;
        }

        map_page_pause_ride(s_sh.map);
        s_sh.pause_auto = false;
        helm_shell_set_paused(true);
        return;
    }

    helm_enter_ride();
}

