    }

    helm_shell_demo_save(false);
    helm_shell_set_paused(false);
    helm_shell_demo_banner(0);

    demo_scene_clear_ride();

    helm_shell_demo_page_clear();

    s_scene = -1;
    s_scene_active = false;
    s_scene_alert_hr = false;
